DROP TABLE IF EXISTS `courses`;
CREATE TABLE `courses` (
  `id` char(36) COLLATE utf8mb4_unicode_ci NOT NULL,
  `course_code` varchar(20) COLLATE utf8mb4_unicode_ci NOT NULL,
  `title` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL,
  `trainer` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL,
  `trainer_type` varchar(20) COLLATE utf8mb4_unicode_ci DEFAULT 'internal',
  `format` varchar(50) COLLATE utf8mb4_unicode_ci NOT NULL,
  `duration_hours` decimal(5,1) NOT NULL,
  `skill_tags` json DEFAULT NULL,
  `rank_targets` json DEFAULT NULL,
  `role_targets` json DEFAULT NULL,
  `rating` decimal(3,1) DEFAULT '0.0',
  `enrolled_count` int DEFAULT '0',
  `type` varchar(20) COLLATE utf8mb4_unicode_ci NOT NULL,
  `min_participants` int DEFAULT NULL,
  `registration_url` text COLLATE utf8mb4_unicode_ci,
  `description` text COLLATE utf8mb4_unicode_ci,
  `xp_reward` int NOT NULL DEFAULT '50',
  `is_active` tinyint(1) DEFAULT '1',
  `status` varchar(20) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'open',
  `material_url` text COLLATE utf8mb4_unicode_ci,
  `session_date` date DEFAULT NULL,
  `session_time` time DEFAULT NULL,
  `location` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `max_participants` int DEFAULT NULL,
  `current_count` int DEFAULT '0',
  `session_status` varchar(20) COLLATE utf8mb4_unicode_ci DEFAULT 'open',
  `created_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `idx_course_code` (`course_code`),
  KEY `idx_session_date` (`session_date`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

